effect.shader:
// O simplex 3D do webgl-noise (Ashima Arts / Ian McEwan, licença MIT), como o AM o escreve: as mesmas constantes e
// a mesma ordem de operações (o ruído é contínuo, mas a mesma ordem dá o mesmo float no mesmo celular).
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 permute(vec4 x) { return mod289(((x * 34.0) + 1.0) * x); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

float snoise(vec3 v) {
    const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod289(i);
    vec4 p = permute(permute(permute(
                 i.z + vec4(0.0, i1.z, i2.z, 1.0))
               + i.y + vec4(0.0, i1.y, i2.y, 1.0))
               + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    float n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);
    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
    p0 *= norm.x;
    p1 *= norm.y;
    p2 *= norm.z;
    p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
}

// A turbulência do AM: |ruído| somado em oitavas, a coordenada dobrada e somada à paralaxe a cada uma.
float turbulence(vec2 st, int OCTAVES, vec2 parallax, float evolution) {
    float value = 0.0;
    float amplitude = .5;
    for (int i = 0; i < OCTAVES; i++) {
        value += amplitude * abs(snoise(vec3(st, evolution)));
        st *= 2.;
        st += parallax;
        amplitude *= .5;
    }
    return value;
}

vec4 preMultiplicada(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// O filtro linear da GPU, à mão, sobre a camada PRÉ-multiplicada (a textura do AM é assim): os 4 pixels em volta,
// presos à borda como o CLAMP_TO_EDGE.
vec4 camadaNoPonto(vec2 uv) {
    ivec2 T = textureSize(inputImg, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = preMultiplicada(texelFetch(inputImg, clamp(a, ivec2(0), m), 0));
    vec4 c10 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(1, 0), ivec2(0), m), 0));
    vec4 c01 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(0, 1), ivec2(0), m), 0));
    vec4 c11 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(1, 1), ivec2(0), m), 0));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// A volta da `acCamadaParaTela`: UV da tela → UV do buffer da camada.
vec2 naCamada(vec2 t) {
    vec3 c = inverse(acCamadaParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

void main() {
    // Os uniforms do AM com os nomes do Nova e a coordenada da camada do AM (o Y para CIMA), como no atual.
    vec2 acScreenSize = acTamanhoDaTela;
    vec2 acLayerSize = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 tela = acTela(acScreenNorm);
    vec2 camada = 0.5 + (naCamada(tela) - 0.5) * acScreenSize / acLayerSize;
    camada.y = 1.0 - camada.y;

    vec2 st;
    if (screenSpace) {
        st = tela;
        st.x *= acScreenSize.x / acScreenSize.y;
    } else {
        st = camada;
        st.x *= acLayerSize.x / acLayerSize.y;
    }
    st += position * vec2(-1., 1.) / 500.;
    vec2 parallax = parr * vec2(-1., 1.) / 100.;

    // O Esticar antigo: um número só, que soma à Escala num eixo (negativo: no outro).
    vec2 scaleVec;
    if (stretch < 0.0) {
        scaleVec = vec2(scale - stretch, scale);
    } else {
        scaleVec = vec2(scale, scale + stretch);
    }
    vec2 sampleCoord;
    if (singleAxis) {
        if (direction == 0) {
            sampleCoord = vec2(0., st.y - 0.5);              // X
        } else if (direction == 1) {
            sampleCoord = vec2(st.x - 0.5, 0.);              // Y
        } else if (direction == 2) {
            sampleCoord = st - 0.5;                          // XY
        } else if (direction == 4) {
            sampleCoord = st - 0.5;                          // φr
        } else if (direction == 5) {
            sampleCoord = vec2(0., length(st - 0.5));        // φ
        } else {
            float tt = abs(atan(st.x - 0.5, st.y - 0.5) / 6.28318) * 2.;
            sampleCoord = vec2(tt, 0.);                      // r
        }
    } else {
        sampleCoord = st - 0.5;
    }

    // A versão 2 MULTIPLICA pela escala (a atual divide).
    float p = turbulence((sampleCoord - 0.5) * scaleVec + 0.5, int(octaves), parallax, evolution + 7391.935 * seed);
    p += (offs - 0.25);
    p *= intensity * 2.0;

    vec2 uv = screenSpace ? tela : camada;
    if (direction == 0) {
        uv.x += p;                                           // X
    } else if (direction == 1) {
        uv.y += p;                                           // Y
    } else if (direction == 2) {
        float q = turbulence((sampleCoord) * scaleVec + 0.5, int(octaves), parallax, evolution + 3937.7249 * (seed + 6.3379));
        q += (offs - 0.25);
        q *= intensity * 2.0;
        uv.x += p;                                           // XY
        uv.y += q;
    } else if (direction == 4) {
        float q = turbulence((sampleCoord) * scaleVec + 0.5, int(octaves), parallax, evolution + 3937.7249 * (seed + 6.3379));
        q += (offs - 0.25);
        q *= intensity * 2.0;
        float cq = cos(q);
        float sq = sin(q);
        uv += normalize(uv - 0.5) * p;                       // φr
        uv *= mat2(cq, sq, -sq, cq);
    } else if (direction == 5) {
        float cq = cos(p);
        float sq = sin(p);
        uv *= mat2(cq, sq, -sq, cq);                         // φ
    } else {
        uv += normalize(uv - 0.5) * p;                       // r
    }

    // De volta à imagem de entrada, como no atual. Sem o corte na borda da tela (o atual tem): fora dela, a borda
    // se repete (CLAMP_TO_EDGE).
    bool naTela = acParaTela == mat3(1.0);
    vec2 b = uv;
    if (!screenSpace) {
        b = 0.5 + (vec2(uv.x, 1.0 - uv.y) - 0.5) * acLayerSize / acScreenSize;
        if (naTela) {
            vec3 c = acCamadaParaTela * vec3(b, 1.0);
            bool afim = acCamadaParaTela[0].z == 0.0 && acCamadaParaTela[1].z == 0.0 && acCamadaParaTela[2].z == 1.0;
            b = afim ? c.xy : c.xy / c.z;
        }
    } else if (!naTela) {
        b = naCamada(uv);
    }

    bool foraDaConta = any(isinf(b)) || any(isnan(b));
    vec4 c = foraDaConta ? preMultiplicada(texture(inputImg, b)) : camadaNoPonto(b);
    fragColor = c.a > 0.0 ? vec4(min(c.rgb / c.a, vec3(1.0)), c.a) : vec4(0.0);
}
